{
  "explanation": "The law of cosines generalizes the Pythagorean theorem to any triangle: c² = a² + b² − 2ab cos(C). When angle C is 90°, cos(C) = 0 so the correction term vanishes and you recover a² + b² = c². For acute angles the correction is negative (c is shorter than the right-triangle case); for obtuse angles cos(C) < 0 so the term becomes positive and c is longer.",
  "manimCode": "const sc = 0.55;
const origin = [-2.5, -1.2, 0];

let lenA = 3.2;
let lenB = 2.6;
let angleC = Math.PI / 3;

function computeVerts() {
  const A = origin;
  const B = [origin[0] + lenA * sc, origin[1], 0];
  const Cx = origin[0] + lenB * sc * Math.cos(angleC);
  const Cy = origin[1] + lenB * sc * Math.sin(angleC);
  const C = [Cx, Cy, 0];
  return { A, B, C };
}

let verts = computeVerts();

const tri = new Polygon({
  vertices: [verts.A, verts.B, verts.C],
  color: WHITE
});
tri.setFill(BLUE_E, 0.35).setStrokeWidth(3);

const dotA = new Dot({ point: verts.A, color: YELLOW });
const dotB = new Dot({ point: verts.B, color: YELLOW });
const dotC = new Dot({ point: verts.C, color: YELLOW });

const labelA = new Text({ text: 'C', color: WHITE, fontSize: 22 });
const labelB = new Text({ text: 'A', color: WHITE, fontSize: 22 });
const labelC = new Text({ text: 'B', color: WHITE, fontSize: 22 });

function placeCornerLabels() {
  verts = computeVerts();
  labelA.moveTo([verts.A[0] - 0.35, verts.A[1] - 0.3, 0]);
  labelB.moveTo([verts.B[0] + 0.35, verts.B[1] - 0.3, 0]);
  labelC.moveTo([verts.C[0], verts.C[1] + 0.35, 0]);
}
placeCornerLabels();

const sideLabelA = new Text({ text: 'b', color: TEAL, fontSize: 26 });
const sideLabelB = new Text({ text: 'a', color: TEAL, fontSize: 26 });
const sideLabelC = new Text({ text: 'c', color: ORANGE, fontSize: 26 });

function placeSideLabels() {
  verts = computeVerts();
  const mid = (p, q, off) => [((p[0]+q[0])/2) + off[0], ((p[1]+q[1])/2) + off[1], 0];
  sideLabelA.moveTo(mid(verts.A, verts.C, [-0.35, 0.15]));
  sideLabelB.moveTo(mid(verts.B, verts.C, [0.35, 0.15]));
  sideLabelC.moveTo(mid(verts.A, verts.B, [0, -0.35]));
}
placeSideLabels();

const formula = new MathTex({ latex: 'c^2 = a^2 + b^2 - 2ab\\cos C' });
await formula.waitForRender();
formula.moveTo([2.8, 2.8, 0]);
formula.scale(0.85);

const pythag = new MathTex({ latex: 'a^2 + b^2' });
await pythag.waitForRender();
pythag.moveTo([2.8, 1.6, 0]);
pythag.scale(0.75);
pythag.setColor(BLUE_B);

const corr = new MathTex({ latex: '-\\,2ab\\cos C' });
await corr.waitForRender();
corr.moveTo([2.8, 0.9, 0]);
corr.scale(0.75);
corr.setColor(ORANGE);

let valueLabel = new Text({ text: '', color: WHITE, fontSize: 22 });
valueLabel.moveTo([2.8, -0.2, 0]);

function updateValueLabel() {
  const cosC = Math.cos(angleC);
  const c2 = lenA * lenA + lenB * lenB - 2 * lenA * lenB * cosC;
  const py = lenA * lenA + lenB * lenB;
  const term = -2 * lenA * lenB * cosC;
  const deg = (angleC * 180 / Math.PI).toFixed(0);
  const str = `C = ${deg}°\ncos C = ${cosC.toFixed(2)}\na²+b² = ${py.toFixed(2)}\ncorr  = ${term.toFixed(2)}\nc²    = ${c2.toFixed(2)}`;
  const pos = valueLabel.getCenter();
  scene.remove(valueLabel);
  valueLabel = new Text({ text: str, color: WHITE, fontSize: 20 });
  valueLabel.moveTo(pos);
  scene.add(valueLabel);
}

function rebuild() {
  verts = computeVerts();
  tri.setVertices([verts.A, verts.B, verts.C]);
  dotA.moveTo(verts.A);
  dotB.moveTo(verts.B);
  dotC.moveTo(verts.C);
  placeCornerLabels();
  placeSideLabels();
  updateValueLabel();
}

scene.add(tri, dotA, dotB, dotC);
scene.add(labelA, labelB, labelC);
scene.add(sideLabelA, sideLabelB, sideLabelC);
scene.add(formula, pythag, corr);
updateValueLabel();

const rightNote = new Text({
  text: 'When C = 90°, cos C = 0 → Pythagorean',
  color: GRAY,
  fontSize: 18
});
rightNote.moveTo([2.8, -2.6, 0]);
scene.add(rightNote);

const controls = new Controls(scene, { position: 'bottom-left', width: 260 });
controls.addSlider({
  label: 'Angle C (deg)',
  min: 20,
  max: 160,
  value: 60,
  step: 1,
  onChange: (v) => {
    angleC = v * Math.PI / 180;
    rebuild();
  }
});
controls.addSlider({
  label: 'Side a',
  min: 1.5,
  max: 4.5,
  value: lenA,
  step: 0.1,
  onChange: (v) => {
    lenA = v;
    rebuild();
  }
});
controls.addSlider({
  label: 'Side b',
  min: 1.5,
  max: 4.5,
  value: lenB,
  step: 0.1,
  onChange: (v) => {
    lenB = v;
    rebuild();
  }
});
controls.addButton({
